[Thinking]
**Providing TCP server code**

I need to provide code for a C TCP server. The answer should be concise, making sure it can be compiled and run without complications. I think using POSIX standards would be a good approach since it will enhance compatibility across different systems. I'll include essential elements like socket creation, binding, listening, and accepting connections so that the user can easily understand the flow. Let's make sure the code is clear and well-structured!
[/Thinking]

Below is a simple TCP/IP server in C for Linux/macOS. It listens on port `8080`, accepts one client at a time, receives data, and sends a reply.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    char buffer[BUFFER_SIZE];

    // Create TCP socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Allow reuse of address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to IP/port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, 5) < 0) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("TCP server listening on port %d...\n", PORT);

    while (1) {
        client_len = sizeof(client_addr);

        // Accept client connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Accept failed");
            continue;
        }

        printf("Client connected: %s:%d\n",
               inet_ntoa(client_addr.sin_addr),
               ntohs(client_addr.sin_port));

        // Receive data from client
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_received > 0) {
            printf("Received: %s\n", buffer);

            // Send response
            const char *response = "Hello from TCP server!\n";
            send(client_fd, response, strlen(response), 0);
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
        } else {
            perror("Receive failed");
        }

        close(client_fd);
    }

    close(server_fd);
    return 0;
}
```

Compile:

```bash
gcc server.c -o server
```

Run:

```bash
./server
```

Test using `telnet` or `nc`:

```bash
nc localhost 8080
```

Then type a message and press Enter.

